// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 fuzzedTimestamp) public {
        vm.assume(fuzzedTimestamp > c.pastBlockTime());
        address sender = address(0x1234);
        vm.deal(sender, 10 ether);

        uint256 blockNum = block.number;

        vm.warp(fuzzedTimestamp);

        vm.prank(sender);
        (bool success,) = address(c).call{value: 10 ether}("");
        require(success, "fallback call failed");

        bool shouldTransferCorrect = (blockNum % 15 == 0);

        uint256 balance = address(c).balance;

        if (shouldTransferCorrect) {
            assertTrue(balance == 0, "balance should be zero if transfer triggered");
        } else {
            assertTrue(balance == 10 ether, "balance should be 10 ether if transfer not triggered");
        }
    }
}
